\def\todown{2.25}

\node[block2, align=center] at (0,0) (nnt) {\textbf{Neural network} (fixed time) \\ $\norm{u(T)-u_\theta(T)}_{L^q(D)}<\epsilon$ \\ \emph{Assumed to be known}};
\node[block3, align=center] at (\tolefta,0) (fno) {\textbf{FNO} \\ $\norm{\cG-\cG_\theta}_{L^2(\cX\times D)}<\epsilon$ \\ \emph{Theorem \ref{thm:nn-to-fno}}};
\node[block, align=center] at (\tolefta+\toleftb,0) (deeponet) {\textbf{DeepONet} \\ $\norm{\cG-\cG_\theta}_{L^2(\cX\times D)}<\epsilon$ \\ \emph{Corollary \ref{cor:nn-to-deeponet}}};
\node[block, align=center] at (0,-\todown) (nn) {\textbf{Neural network} (space-time) \\ $\norm{u-u_\theta}_{L^q([0,T]\times D)}<\epsilon$ \\ \emph{Theorem \ref{thm:nn-to-pinn}}};
\node[block, align=center] at (0,-\todown-\todown) (pinn) {\textbf{PINN} \\ $\norm{\cL(u_\theta)}_{L^q([0,T]\times D)}<\epsilon$ \\ \emph{Theorem \ref{thm:nn-to-pinn}}};
\node[block3, align=center] at (\tolefta,-\todown-\todown) (pino) {\textbf{Physics-informed FNO} \\ $\norm{\cL(\cG_\theta)}_{L^2(\cX\times \Omega)}<\epsilon$ \\ \emph{Theorem \ref{thm:deeponet-to-pido}}};
\node[block, align=center] at (\tolefta+\toleftb,-\todown-\todown) (pido) {\textbf{Physics-informed DeepONet} \\ $\norm{\cL(\cG_\theta)}_{L^2(\cX\times\Omega)}<\epsilon$ \\ \emph{Theorem \ref{thm:deeponet-to-pido} \& \ref{thm:nn-to-pido}}};

\path [line] (nnt) -- (nn) node [midway, right] {\emph{A}};
\path [line] (nn) -- (pinn) node [midway, right] {\emph{B}};
\path [line] (fno) -- (pino) node [midway, right] {\emph{B}};
\path [line] (deeponet) -- (pido) node [midway, right] {\emph{B}};
\path [line] (nnt) -- (fno) node [midway, above] {\emph{C}};
\path [line] (pinn) -- (pino) node [midway, above] {\emph{C}};
\path [line] (fno) -- (deeponet) node [midway, above] {\emph{D}};
\path [line] (pino) -- (pido) node [midway, above] {\emph{D}};

\end{tikzpicture}
\end{center}
    \caption{Flowchart of the structure of the results in this paper, with $q\in\{2,\infty\}$. The letters reflect the techniques used in the proofs: \emph{A} uses Taylor approximations (Section \ref{sec:taylor}), \emph{B} is based on finite difference approximations (Section \ref{sec:taylor}), \emph{C} uses trigonometric polynomial interpolation (Section \ref{sec:fourier}) and \emph{D} uses the connection between FNOs and DeepONets (Section \ref{sec:fourier}). }
    \label{fig:flowchart}
\end{figure}

